ST.xhtml:
// ═══════════════════════════════════════════════════════════════
// 🛗 §1 TREUIL M1 (Retenue) — conditions + interlock + sorties
// ═══════════════════════════════════════════════════════════════
// 👁️ D'un coup d'œil : ce qui active/désactive la sortie M1.
//   - M1InterlockEnable      : gate finale (Enable ET pas de PowerCutOff)
//   - M1PowerCutOffSafetyInfo: défauts qui COUPENT la puissance
//   - M1SafeStopSafetyInfo   : défauts qui font SafeStop (rampe rapide)
//   - AscentPermit/DescendPermit : permis directionnels reconsommes par la barriere finale
//   - M1BlockedBySafetyInfo  : synthese (PowerCutOff OU SafeStop)
// Sources : PRG_04 (WinchM1FinalInterlockRequest / WinchM1Safety).

M1InterlockEnable := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.Enable
                      AND NOT PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.PowerCutOff;

M1PowerCutOffSafetyInfo := PRG_04_Treuils_Benne.Data.WinchM1Safety.PowerCutOff
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaA
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaB
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaC
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaD
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaE
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ThermalFault;

M1SafeStopSafetyInfo := PRG_04_Treuils_Benne.Data.WinchM1Safety.SafeStop
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.Error
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorOperatorComm
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorEncoder
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorPhaseRotation
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorOppositeDir
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorNoMovement;

M1BlockedBySafetyInfo := M1PowerCutOffSafetyInfo OR M1SafeStopSafetyInfo;

instWinchOutputInterlockM1(
    Enable                     := M1InterlockEnable,
    Reset                      := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged      := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.PowerContactorEngaged,
    SafeStop                   := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.SafeStop,
    AscentPermit               := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.AscentPermit,
    DescendPermit              := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.DescendPermit,
    BrakeFeedback              := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.BrakeFeedback,
    FwdRevSpeedFeedbackOff     := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.FwdRevSpeedFeedbackOff,
    RequestedRelayFwd          := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedRelayFwd,
    RequestedRelayRev          := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedRelayRev,
    RequestedContactor1        := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedContactor1,
    RequestedContactor2        := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedContactor2,
    RequestedContactor3        := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedContactor3,
    RequestedContactor4        := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedContactor4,
    RequestedStep               := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedStep
);

M1RelayFwd        := instWinchOutputInterlockM1.RelayFwd;
M1RelayRev        := instWinchOutputInterlockM1.RelayRev;
M1SpeedContactor1 := instWinchOutputInterlockM1.Contactor1;
M1SpeedContactor2 := instWinchOutputInterlockM1.Contactor2;
M1SpeedContactor3 := instWinchOutputInterlockM1.Contactor3;
M1SpeedContactor4 := instWinchOutputInterlockM1.Contactor4;
// Recalcul independant sur les DQ finaux (pas une recopie de BrakeCmd).
M1BrakeCmd        := M1RelayFwd OR M1RelayRev;

// ── Sorties physiques M1 ──
M1_RelayAscent_DQ            := M1RelayFwd;
M1_RelayDescent_DQ           := M1RelayRev;
M1_SpeedContactor_1_DQ       := M1SpeedContactor1;
M1_SpeedContactor_2_DQ       := M1SpeedContactor2;
M1_SpeedContactor_3_DQ       := M1SpeedContactor3;
M1_SpeedContactor_4_DQ       := M1SpeedContactor4;
M1_BrakeRelease_RQ           := M1BrakeCmd;

// ── Bus inter-PRG M1 ──
Data.M1RelayFwd            := M1RelayFwd;
Data.M1RelayRev            := M1RelayRev;
Data.M1SpeedContactor1     := M1SpeedContactor1;
Data.M1SpeedContactor2     := M1SpeedContactor2;
Data.M1SpeedContactor3     := M1SpeedContactor3;
Data.M1SpeedContactor4     := M1SpeedContactor4;
Data.M1BrakeCmd            := M1BrakeCmd;

// ═══════════════════════════════════════════════════════════════
// 🛗 §2 TREUIL M2 (Benne) — conditions + interlock + sorties
// ═══════════════════════════════════════════════════════════════
// 👁️ Même lecture que M1 : gate finale, défauts PowerCutOff / SafeStop, synthèse.
// Sources : PRG_04 (WinchM2FinalInterlockRequest / WinchM2Safety / BucketState).

M2InterlockEnable := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.Enable
                      AND NOT PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.PowerCutOff;

M2PowerCutOffSafetyInfo := PRG_04_Treuils_Benne.Data.WinchM2Safety.PowerCutOff
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorMecaA
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorMecaB
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorMecaC
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorMecaD
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorMecaE
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ThermalFault;

M2SafeStopSafetyInfo := PRG_04_Treuils_Benne.Data.WinchM2Safety.SafeStop
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.Error
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorOperatorComm
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorEncoder
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorPhaseRotation
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorOppositeDir
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorNoMovement
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.SlackCable
                     OR PRG_04_Treuils_Benne.Data.BucketState.Error
                     OR PRG_04_Treuils_Benne.Data.BucketState.CoupledMotionBlockedByBucket;

M2BlockedBySafetyInfo := M2PowerCutOffSafetyInfo OR M2SafeStopSafetyInfo;

instWinchOutputInterlockM2(
    Enable                     := M2InterlockEnable,
    Reset                      := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged      := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.PowerContactorEngaged,
    SafeStop                   := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.SafeStop,
    AscentPermit               := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.AscentPermit,
    DescendPermit              := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.DescendPermit,
    BrakeFeedback              := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.BrakeFeedback,
    FwdRevSpeedFeedbackOff     := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.FwdRevSpeedFeedbackOff,
    RequestedRelayFwd          := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedRelayFwd,
    RequestedRelayRev          := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedRelayRev,
    RequestedContactor1        := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedContactor1,
    RequestedContactor2        := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedContactor2,
    RequestedContactor3        := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedContactor3,
    RequestedContactor4        := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedContactor4,
    RequestedStep               := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedStep
);

M2RelayFwd        := instWinchOutputInterlockM2.RelayFwd;
M2RelayRev        := instWinchOutputInterlockM2.RelayRev;
M2SpeedContactor1 := instWinchOutputInterlockM2.Contactor1;
M2SpeedContactor2 := instWinchOutputInterlockM2.Contactor2;
M2SpeedContactor3 := instWinchOutputInterlockM2.Contactor3;
M2SpeedContactor4 := instWinchOutputInterlockM2.Contactor4;
// Recalcul independant, voir M1.
M2BrakeCmd        := M2RelayFwd OR M2RelayRev;

// ── Sorties physiques M2 ──
M2_RelayAscent_Close_DQ      := M2RelayFwd;
M2_RelayDescent_Open_DQ      := M2RelayRev;
M2_SpeedContactor_1_DQ       := M2SpeedContactor1;
M2_SpeedContactor_2_DQ       := M2SpeedContactor2;
M2_SpeedContactor_3_DQ       := M2SpeedContactor3;
M2_SpeedContactor_4_DQ       := M2SpeedContactor4;
M2_BrakeRelease_RQ           := M2BrakeCmd;

// ── Bus inter-PRG M2 ──
Data.M2RelayFwd            := M2RelayFwd;
Data.M2RelayRev            := M2RelayRev;
Data.M2SpeedContactor1     := M2SpeedContactor1;
Data.M2SpeedContactor2     := M2SpeedContactor2;
Data.M2SpeedContactor3     := M2SpeedContactor3;
Data.M2SpeedContactor4     := M2SpeedContactor4;
Data.M2BrakeCmd            := M2BrakeCmd;

// ═══════════════════════════════════════════════════════════════
// ↔️ §3 TRANSLATION M3 (variateur AC600) — conditions + interlock + sorties
// ═══════════════════════════════════════════════════════════════
// 👁️ Même lecture : gate finale, défauts PowerCutOff / SafeStop, synthèse.
// Sources : PRG_05 (TranslationFinalInterlockRequest / TranslationSafety).

M3InterlockEnable := PRG_05_Translation.Data.TranslationFinalInterlockRequest.Enable
                      AND NOT PRG_05_Translation.Data.TranslationFinalInterlockRequest.PowerCutOff;

M3PowerCutOffSafetyInfo := PRG_05_Translation.Data.TranslationSafety.PowerCutOff
                        OR PRG_05_Translation.Data.TranslationSafety.ErrorMecaA
                        OR PRG_05_Translation.Data.TranslationSafety.ErrorMecaB
                        OR PRG_05_Translation.Data.TranslationSafety.ErrorBrakeThermal;

M3SafeStopSafetyInfo := PRG_05_Translation.Data.TranslationSafety.SafeStop
                     OR PRG_05_Translation.Data.TranslationSafety.Error
                     OR PRG_05_Translation.Data.TranslationSafety.ErrorOperatorComm
                     OR PRG_05_Translation.Data.TranslationSafety.ErrorDriveComm
                     OR PRG_05_Translation.Data.TranslationSafety.ErrorPhaseRotation
                     OR PRG_05_Translation.Data.TranslationSafety.ErrorLimitSwitch
                     OR PRG_05_Translation.Data.TranslationSafety.ErrorSensorIncoherent;

M3BlockedBySafetyInfo := M3PowerCutOffSafetyInfo OR M3SafeStopSafetyInfo;

instTranslationOutputInterlockM3(
    Enable                     := M3InterlockEnable,
    Reset                      := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged      := PRG_05_Translation.Data.TranslationFinalInterlockRequest.PowerContactorEngaged,
    SafeStop                   := PRG_05_Translation.Data.TranslationFinalInterlockRequest.SafeStop,
    EffectivePermitM3_Tremie   := PRG_05_Translation.Data.TranslationFinalInterlockRequest.EffectivePermitM3_Tremie,
    EffectivePermitM3_Maintenance := PRG_05_Translation.Data.TranslationFinalInterlockRequest.EffectivePermitM3_Maintenance,
    BrakeReleaseRequest        := PRG_05_Translation.Data.TranslationFinalInterlockRequest.BrakeReleaseRequest,
    BrakeCommandOpenConfirmed  := PRG_05_Translation.Data.TranslationFinalInterlockRequest.BrakeCommandOpenConfirmed,
    RequestedDriveControlWord  := PRG_05_Translation.Data.TranslationFinalInterlockRequest.RequestedDriveControlWord,
    RequestedDriveFreqHz       := PRG_05_Translation.Data.TranslationFinalInterlockRequest.RequestedDriveFreqHz
);

TranslationBrakeCmd := instTranslationOutputInterlockM3.BrakeCmd;

// ── Sorties physiques M3 ──
M3_BrakeRelease_RQ           := TranslationBrakeCmd;
M3_CommandWord               := instTranslationOutputInterlockM3.DriveControlWord;
M3_SetpointFrequencyHz       := instTranslationOutputInterlockM3.DriveFreqCmdWord;

// ── Bus inter-PRG M3 ──
Data.TranslationBrakeCmd   := TranslationBrakeCmd;

// ═══════════════════════════════════════════════════════════════
// 🪝 §4 KOBOLD (capteur fond) — commande + sortie
// ═══════════════════════════════════════════════════════════════
// Source : PRG_04 (KoboldContactorCmdArbitrated).
KoboldContactorCmd := PRG_04_Treuils_Benne.Data.KoboldContactorCmdArbitrated;
M1_M2_KoboldMeasureEnable_DQ := KoboldContactorCmd;

// ═══════════════════════════════════════════════════════════════
// 🛡️ §5 AU / MAINTIEN PUISSANCE — coupure + réarmement + sorties
// ═══════════════════════════════════════════════════════════════
// 👁️ D'un coup d'œil : ce qui coupe la puissance (PowerCutOffReq) et ce qui
//    maintient/réarme (instSafetyEmergencyManagement) → sorties physiques.
// Sources : PRG_04/05 (PowerCutOff), GVL_IHM (ArmRequest / BtnEmergencyCutOff),
//           PRG_02 (EmergencyChainClosed / PowerContactorEngaged).

// PowerCutOffReq = agrégation OU strict des demandes de coupure des trois procédés (M5, A-04).
PowerCutOffReq := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.PowerCutOff
               OR PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.PowerCutOff
               OR PRG_05_Translation.Data.TranslationFinalInterlockRequest.PowerCutOff;

instSafetyEmergencyManagement(
    Enable := TRUE,
    Reset := PRG_07_Supervision.FaultMachineReset_IHM,
    ArmRequest := GVL_IHM.Emergency.Cmd.BtnEmergencyArming,
    EmergencyChainClosed := PRG_02_Acquisition.HwIn.Machine.EmergencyChainClosed_DI,
    PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    PowerCutOffRequest := PowerCutOffReq,
    BtnEmergencyCutOff := GVL_IHM.Emergency.Cmd.BtnEmergencyCutOff
);

// ── Ordres AU (logique) — sorties structurées Status : ST_Safety_Emergency_Status + Cmd : ST_Safety_Emergency_Cmd ──
PowerKeepAliveACmd := instSafetyEmergencyManagement.Cmd.MaintainA_Cmd;
PowerKeepAliveBCmd := instSafetyEmergencyManagement.Cmd.MaintainB_Cmd;
EmergencyArmingCmd := instSafetyEmergencyManagement.Cmd.ArmPulse_Cmd;

// ── Sorties physiques AU ──
PowerKeepAlive_A_RQ          := PowerKeepAliveACmd;
PowerKeepAlive_B_RQ          := PowerKeepAliveBCmd;
EmergencyArming_RQ           := EmergencyArmingCmd;

// ── Bus inter-PRG AU ──
Data.PowerKeepAliveACmd    := PowerKeepAliveACmd;
Data.PowerKeepAliveBCmd    := PowerKeepAliveBCmd;
Data.EmergencyArmingCmd    := EmergencyArmingCmd;
Data.TestCutActive         := instSafetyEmergencyManagement.Cmd.TestCutActive;
Data.PowerCutOffRequest    := PowerCutOffReq;

// ── Diagnostics chaîne AU (DUT structurés State/Diag, source unique) ──
EmergencyState := instSafetyEmergencyManagement.Status.State;
EmergencyDiag := instSafetyEmergencyManagement.Status.Diag;
EmergencyReady := instSafetyEmergencyManagement.Status.Ready;
EmergencyDone := instSafetyEmergencyManagement.Status.Done;
EmergencyFault := instSafetyEmergencyManagement.Status.Fault;
EmergencyOperatorMessage := instSafetyEmergencyManagement.Status.OperatorMessage;
PowerCutOffActive := PowerCutOffReq;

// === IMPLEMENTATION ===

{region "§1 Fronts de commande"}
// 🔄 Fronts
EnableRising(CLK := Enable);
ResetEdge(CLK := Reset);
ArmReqEdge(CLK := ArmRequest);
{endregion}

{region "§2 Gate Enable (neutralisation fail-safe)"}
// 🛑 GATE — neutralisation si désactivé : réinitialise l'état interne de la séquence.
// Les sorties physiques sont forcées à FALSE par la projection fail-safe (§10) ; le socle
// défaut reste appelé (§9) pour maintenir le latch non acquitté.
IF NOT Enable THEN
    ArmingSeqStep := CST_STEP_IDLE;
    ForceTestA := FALSE;
    ForceTestB := FALSE;
    StartupFail := FALSE;
    StartupCheckDone := FALSE;
    StartupCheckOK := FALSE;
    RedundancyTestFailed := FALSE;
    EmergencyArmingFailed := FALSE;
    EmergencyArmingLockoutActive := FALSE;
    Armable := FALSE;
    ArmingBusy := FALSE;
    LastAbortStep := CST_STEP_IDLE;
    LastAbortCause := INT_TO_WORD(CST_ABORT_NONE);
    // Neutralisation = coupure surveillance, pas un defaut : Cause et Ack repartent propres
    RedundancyTestFailedCause := FALSE;
    RedundancyTestFailedAck := TRUE;
    EmergencyArmingFailedCause := FALSE;
    EmergencyArmingFailedAck := TRUE;
    TonTestA(IN := FALSE);
    TonRestoreA(IN := FALSE);
    TonTestB(IN := FALSE);
    TonRestoreB(IN := FALSE);
    TonArmingPulse(IN := FALSE);
    TonArmingConfirm(IN := FALSE);
    TonArmingLockout(IN := FALSE);
    TonRedundancyDisplay(IN := FALSE);
    TonArmingFailedDisplay(IN := FALSE);
END_IF;
{endregion}

{region "§3 Autotest demarrage"}
// 🏁 AUTOTEST DÉMARRAGE (§5.4 AF01) — vérifications synchrones 1 cycle au 1er Enable=TRUE
IF Enable THEN
    IF EnableRising.Q THEN
        StartupCheckDone := FALSE;
    END_IF;

    IF NOT StartupCheckDone THEN
        // Exécute les 4 contrôles en 1 cycle
        StartupCheckOK := EmergencyChainClosed          // 1. Boucle AU fermée
                          AND NOT PowerContactorEngaged // 2. Contacteur au repos
                          AND (ArmingSeqStep = CST_STEP_IDLE); // 4. Pas de séquence résiduelle
        StartupCheckDone := TRUE;
        StartupFail := NOT StartupCheckOK;
        // StartupFail est laté via le socle FB_FaultCore (§9) : il reste jusqu'au front Reset.
    END_IF;
END_IF;
{endregion}

{region "§4 Acquittement defauts"}
// 🔍 ACQUITTEMENT DES DÉFAUTS (pattern Cause/Ack — §3.4bis AF01, §9 STD)
// ⚠️ Reset acquitte l'affichage (Ack:=TRUE). La cause de redondance reste verrouillée
// jusqu'au prochain test physique. L'échec d'armement précédent est réinitialisé pour autoriser un réessai.
IF Enable THEN
    IF ResetEdge.Q THEN
        RedundancyTestFailedAck := TRUE;
        EmergencyArmingFailedCause := FALSE;
        EmergencyArmingFailedAck := TRUE;
        EmergencyArmingLockoutActive := FALSE;
        StartupFail := FALSE;
    END_IF;
END_IF;
{endregion}

{region "§5 Sequence rearmement AU"}
IF Enable THEN
    // 🛑 Coupure immédiate de toute séquence en cours
    IF ArmingSeqStep <> CST_STEP_IDLE THEN
        IF BtnEmergencyCutOff THEN
            // Avortement volontaire : pas d'alarme d'échec
            LastAbortStep := ArmingSeqStep;
            LastAbortCause := INT_TO_WORD(CST_ABORT_CUT_IHM);
            ArmingSeqStep := CST_STEP_IDLE;
        ELSIF PowerCutOffRequest THEN
            // Avortement sécurité d'urgence : coupure métier (PAS un défaut d'armement).
            // Lockout 5s + interlock (Armable/Maintain* bloqués par PowerCutOffRequest).
            // Ne pose PAS EmergencyArmingFailedCause : pas de fausse alarme "échec armement".
            EmergencyArmingLockoutActive := TRUE;
            LastAbortStep := ArmingSeqStep;
            LastAbortCause := INT_TO_WORD(CST_ABORT_POWER_CUTOFF);
            ArmingSeqStep := CST_STEP_IDLE;
        ELSIF (ArmingSeqStep = CST_STEP_PULSE OR ArmingSeqStep = CST_STEP_CONFIRM) AND NOT EmergencyChainClosed THEN
            // Chute boucle matérielle : alarme d'échec + verrouillage 5s
            EmergencyArmingFailedCause := TRUE;
            EmergencyArmingLockoutActive := TRUE;
            LastAbortStep := ArmingSeqStep;
            LastAbortCause := INT_TO_WORD(CST_ABORT_CHAIN_DROP);
            ArmingSeqStep := CST_STEP_IDLE;
        END_IF;
    END_IF;

    // 🚦 PRÉCONDITIONS D'ARMEMENT — source unique (Armable = State.Armable).
    // ⚠️ Armable_NoBlock SANS `NOT RedundancyTestFailedCause` : la cause de redondance est
    //    latée mais la séquence d'armement la re-teste (§5 étape 1/3) : l'armement reste donc
    //    réellement possible (et sûr) tant que les autres préconditions sont réunies. Afficher
    //    le bouton « Armable » sur cette cause seule bloquait le réarmement après acquittement
    //    (Reset ne purge pas la Cause, cf. §4) alors que l'armement était permis.
    Armable_ChainOk := EmergencyChainClosed AND NOT BtnEmergencyCutOff AND NOT PowerCutOffRequest;
    Armable_Idle := (ArmingSeqStep = CST_STEP_IDLE);
    Armable_NoBlock := NOT EmergencyArmingLockoutActive AND NOT PowerContactorEngaged;
    Armable := Armable_ChainOk AND Armable_Idle AND Armable_NoBlock;
    // CASE à étiquettes littérales : 0..6 = CST_STEP_* (GVL_Safety_Emergency).
    // La CI STruCpp exige ces littéraux pour les étiquettes CASE.
    CASE ArmingSeqStep OF
        0: // CST_STEP_IDLE
            ForceTestA := FALSE;
            ForceTestB := FALSE;
            TonTestA(IN := FALSE, PT := CST_TestDuration);
            TonRestoreA(IN := FALSE, PT := CST_TestDuration);
            TonTestB(IN := FALSE, PT := CST_TestDuration);
            TonRestoreB(IN := FALSE, PT := CST_TestDuration);
            TonArmingPulse(IN := FALSE, PT := CST_ArmingPulseDuration);
            TonArmingConfirm(IN := FALSE, PT := CST_ArmingConfirmTimeout);

            IF ArmReqEdge.Q AND Armable THEN
                RedundancyTestFailedCause := FALSE;
                EmergencyArmingFailedCause := FALSE;
                ArmingSeqStep := CST_STEP_TEST_A;
            END_IF;

        1: // CST_STEP_TEST_A
            ForceTestA := TRUE;
            ForceTestB := FALSE;
            TonTestA(IN := TRUE, PT := CST_TestDuration);

            IF TonTestA.Q THEN
                ForceTestA := FALSE;
                IF EmergencyChainClosed THEN
                    RedundancyTestFailedCause := TRUE;
                    LastAbortStep := CST_STEP_TEST_A;
                    LastAbortCause := INT_TO_WORD(CST_ABORT_REDUNDANCY_A);
                    ArmingSeqStep := CST_STEP_IDLE;
                ELSE
                    ArmingSeqStep := CST_STEP_RESTORE_A;
                END_IF;
            END_IF;

        2: // CST_STEP_RESTORE_A
            ForceTestA := FALSE;
            ForceTestB := FALSE;
            TonRestoreA(IN := TRUE, PT := CST_TestDuration);

            IF TonRestoreA.Q THEN
                IF EmergencyChainClosed THEN
                    ArmingSeqStep := CST_STEP_TEST_B;
                ELSE
                    LastAbortStep := CST_STEP_RESTORE_A;
                    LastAbortCause := INT_TO_WORD(CST_ABORT_TIMEOUT_RESTORE_A);
                    ArmingSeqStep := CST_STEP_IDLE;
                END_IF;
            END_IF;

        3: // CST_STEP_TEST_B
            ForceTestA := FALSE;
            ForceTestB := TRUE;
            TonTestB(IN := TRUE, PT := CST_TestDuration);

            IF TonTestB.Q THEN
                ForceTestB := FALSE;
                IF EmergencyChainClosed THEN
                    RedundancyTestFailedCause := TRUE;
                    LastAbortStep := CST_STEP_TEST_B;
                    LastAbortCause := INT_TO_WORD(CST_ABORT_REDUNDANCY_B);
                    ArmingSeqStep := CST_STEP_IDLE;
                ELSE
                    ArmingSeqStep := CST_STEP_RESTORE_B;
                END_IF;
            END_IF;

        4: // CST_STEP_RESTORE_B
            ForceTestA := FALSE;
            ForceTestB := FALSE;
            TonRestoreB(IN := TRUE, PT := CST_TestDuration);

            IF TonRestoreB.Q THEN
                IF EmergencyChainClosed THEN
                    ArmingSeqStep := CST_STEP_PULSE;
                ELSE
                    LastAbortStep := CST_STEP_RESTORE_B;
                    LastAbortCause := INT_TO_WORD(CST_ABORT_TIMEOUT_RESTORE_B);
                    ArmingSeqStep := CST_STEP_IDLE;
                END_IF;
            END_IF;

        5: // CST_STEP_PULSE
            ForceTestA := FALSE;
            ForceTestB := FALSE;
            TonArmingPulse(IN := TRUE, PT := CST_ArmingPulseDuration);

            IF TonArmingPulse.Q THEN
                ArmingSeqStep := CST_STEP_CONFIRM;
            END_IF;

        6: // CST_STEP_CONFIRM
            ForceTestA := FALSE;
            ForceTestB := FALSE;
            TonArmingConfirm(IN := TRUE, PT := CST_ArmingConfirmTimeout);

            IF PowerContactorEngaged THEN
                EmergencyArmingLockoutActive := FALSE;
                ArmingSeqStep := CST_STEP_IDLE;
            ELSIF TonArmingConfirm.Q THEN
                EmergencyArmingFailedCause := TRUE;
                EmergencyArmingLockoutActive := TRUE;
                LastAbortStep := CST_STEP_CONFIRM;
                LastAbortCause := INT_TO_WORD(CST_ABORT_TIMEOUT_CONTACTOR);
                ArmingSeqStep := CST_STEP_IDLE;
            END_IF;

        ELSE
            ForceTestA := FALSE;
            ForceTestB := FALSE;
            EmergencyArmingFailedCause := TRUE;
            EmergencyArmingLockoutActive := TRUE;
            LastAbortStep := ArmingSeqStep;
            LastAbortCause := INT_TO_WORD(CST_ABORT_INVALID_STEP);
            ArmingSeqStep := CST_STEP_IDLE;
    END_CASE;

    // ⏱️ Séquence de verrouillage temporel (5s)
    TonArmingLockout(IN := EmergencyArmingLockoutActive, PT := CST_ArmingLockout);
    IF TonArmingLockout.Q THEN
        EmergencyArmingLockoutActive := FALSE;
    END_IF;
END_IF;
{endregion}

{region "§6 Gestion cause et acquittement"}
// PATTERN CAUSE/ACK — détection ré-apparition + acquittement (§3.4bis AF01, §9 STD)
// L'interlock sécurité (ci-dessous, arbitrage Cmd/Armable) utilise TOUJOURS la Cause brute,
// jamais l'Ack : l'acquittement opérateur n'ouvre jamais un interlock de sécurité.
IF Enable THEN
    RedundancyCauseEdge(CLK := RedundancyTestFailedCause);
    IF RedundancyCauseEdge.Q THEN
        RedundancyTestFailedAck := FALSE; // nouvelle occurrence -> ré-alarme, ré-acquittement requis
    END_IF;

    ArmingFailedCauseEdge(CLK := EmergencyArmingFailedCause);
    IF ArmingFailedCauseEdge.Q THEN
        EmergencyArmingFailedAck := FALSE;
    END_IF;
END_IF;
{endregion}

{region "§7 Etats publics (interlock sur Cause brute)"}
// 🚦 ÉTATS PUBLICS — interlock sur Cause brute (jamais sur l'Ack)
IF Enable THEN
    ArmingBusy := (ArmingSeqStep <> CST_STEP_IDLE) OR EmergencyArmingLockoutActive;
END_IF;
{endregion}

{region "§8 Affichage defauts IHM"}
// 📤 AFFICHAGE IHM — debounce anti-clignotement (Cause lissée) OR NOT Ack (§9 STD)
// ⚠️ Uniquement pour l'affichage : l'action de sécurité ci-dessus (§5/§6) reste instantanée
// sur la Cause brute, jamais retardée par ce debounce.
IF Enable THEN
    TonRedundancyDisplay(IN := RedundancyTestFailedCause, PT := CST_FaultDisplayDebounce);
    RedundancyTestFailed := TonRedundancyDisplay.Q OR NOT RedundancyTestFailedAck;

    TonArmingFailedDisplay(IN := EmergencyArmingFailedCause, PT := CST_FaultDisplayDebounce);
    EmergencyArmingFailed := TonArmingFailedDisplay.Q OR NOT EmergencyArmingFailedAck;
END_IF;
{endregion}

{region "§9 Synthese defaut via socle FB_FaultCore"}
// 📤 SYNTHÈSE DES ERREURS — socle standard FB_FaultCore (vue live + vue latchée).
//    Chaque cause est exprimée EN CLAIR (ST_FaultCause) ; le socle en déduit ST_Fault.
//    StartupFail est une cause indépendante (index 3, Latching=TRUE) : latée jusqu'au front Reset.
//    Mapping bits (préservé pour FB_Hmi_BannerFormatter / PRG_07) :
//      bit0 = RedundancyTestFailed, bit1 = EmergencyArmingFailed, bit3 = StartupFail.
instCauses[0].Active := RedundancyTestFailed; instCauses[0].Latching := TRUE;
instCauses[0].Texte := 'Defaut redondance contacteurs AU';
instCauses[1].Active := EmergencyArmingFailed; instCauses[1].Latching := TRUE;
instCauses[1].Texte := 'Echec rearmement contacteur AU (timeout)';
instCauses[2].Active := FALSE; instCauses[2].Latching := FALSE;
instCauses[2].Texte := '';
instCauses[3].Active := StartupFail; instCauses[3].Latching := TRUE;
instCauses[3].Texte := 'Echec autotest demarrage AU';

// Appel du socle TOUJOURS (même Enable=FALSE) : le Reset reste effectif et le latch non
// acquitté reste publié (fail-safe, pas d'effacement silencieux sur bascule Enable OFF→ON).
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Status.Fault := instFault.Fault; // source de verite = socle
{endregion}

{region "§10 Projection sorties physiques et bus"}
// ⚡ Sorties physiques — Enable gate fail-safe + interlock Cause brute.
// 🛡️ Maintien conditionné sur (chaîne fermée OU séquence en cours) : hors séquence, une
// boucle AU ouverte (coup-de-poing) coupe le maintien (fail-safe). Pendant la séquence, la
// chaîne est volontairement ouverte par ForceTestA/B -> le maintien reste autorisé (restauration).
Maintain_ChainOk := (EmergencyChainClosed OR (ArmingSeqStep <> CST_STEP_IDLE));
Maintain_NoCutOff := NOT PowerCutOffRequest AND NOT BtnEmergencyCutOff;
MaintainA_NoFault := NOT ForceTestA AND NOT RedundancyTestFailedCause;
MaintainB_NoFault := NOT ForceTestB AND NOT RedundancyTestFailedCause;
MaintainA_NoBlock := Maintain_NoCutOff AND MaintainA_NoFault;
MaintainB_NoBlock := Maintain_NoCutOff AND MaintainB_NoFault;
Cmd.MaintainA_Cmd := Enable AND Maintain_ChainOk AND MaintainA_NoBlock;
Cmd.MaintainB_Cmd := Enable AND Maintain_ChainOk AND MaintainB_NoBlock;
Cmd.ArmPulse_Cmd  := Enable AND (ArmingSeqStep = CST_STEP_PULSE) AND NOT BtnEmergencyCutOff AND NOT PowerCutOffRequest;
// 🧪 TestCutActive : signale à la simulation qu'un canal est coupé pour le test de
// redondance A/B (ForceTestA/B). La simulation ouvre alors la boucle AU (SimChainOk=FALSE)
// pour que le test valide la chute de chaîne — sans dépendre de PowerCutOff_A/B (cercle cassé).
Cmd.TestCutActive := Enable AND (ForceTestA OR ForceTestB);

// 🚦 Bus d'état public
Status.State.ChainOk     := Enable AND EmergencyChainClosed;
Status.State.ContactorOk := Enable AND PowerContactorEngaged;
Status.State.Step        := ArmingSeqStep;
Status.State.Armable     := Armable;
Status.State.ArmingBusy  := ArmingBusy;

// 🛡️ Bus diagnostic public (vue live du socle)
Status.Diag.Error                := Status.Fault.Error;
Status.Diag.ErrorId              := Status.Fault.ErrorId;
Status.Diag.RedundancyTestFailed := RedundancyTestFailed;
Status.Diag.ArmFailed            := EmergencyArmingFailed;
Status.Diag.LockoutActive        := EmergencyArmingLockoutActive;
Status.Diag.LastAbortStep        := LastAbortStep;
Status.Diag.LastAbortCause       := LastAbortCause;
{endregion}

{region "§11 Etats publics IEC + message operateur"}
// 📤 ÉTATS PUBLICS IEC
Status.Ready := Enable AND NOT StartupFail;
Status.Done  := PowerContactorEngaged;

// 💬 MESSAGE OPÉRATEUR — un message explicite par état et par problème de la chaîne AU.
// Priorité : problème de sécurité > état de séquence. Fusionné côté IHM dans les messages
// opérateurs (FB_Hmi_BannerFormatter lit Diag.ErrorId / scalaires).
IF NOT Enable THEN
    Status.OperatorMessage := 'AU neutralisee (Enable=FALSE)';
ELSIF StartupFail THEN
    Status.OperatorMessage := 'AU: autotest demarrage echoue - verifier boucle/contacteur puis Reset';
ELSIF RedundancyTestFailed THEN
    Status.OperatorMessage := 'AU: defaut redondance contacteurs - verifier puis Reset';
ELSIF EmergencyArmingFailed THEN
    IF LastAbortCause = INT_TO_WORD(CST_ABORT_INVALID_STEP) THEN
        Status.OperatorMessage := 'AU: etape sequence invalide - verifier puis Reset';
    ELSE
        Status.OperatorMessage := 'AU: echec rearmement contacteur (timeout) - verifier puis rearmer';
    END_IF;
ELSIF PowerCutOffRequest THEN
    Status.OperatorMessage := 'AU: coupure securite metier active - lever la cause puis rearmer';
ELSIF BtnEmergencyCutOff THEN
    Status.OperatorMessage := 'AU: coupure urgence IHM active - relacher puis rearmer';
ELSIF NOT EmergencyChainClosed THEN
    Status.OperatorMessage := 'AU: boucle urgence ouverte - verifier coup-de-poing';
ELSIF EmergencyArmingLockoutActive THEN
    Status.OperatorMessage := 'AU: verrouillage 5s actif - attendre puis rearmer';
ELSE
    // 📌 Étiquettes en LITTÉRAUX numériques (pattern PresetSeqStep / FB_Encoder_Abs) :
    //    le jumeau CI STruCpp ne génère pas d'étiquettes CASE constexpr depuis des constantes
    //    GVL (IECVar non-constexpr) ; CODESYS accepte les deux formes. La correspondance
    //    symbolique vit ici : 0..6 = CST_STEP_* (GVL_Safety_Emergency).
    CASE ArmingSeqStep OF
        0: // IDLE (= CST_STEP_IDLE)
            Status.OperatorMessage := 'AU: repos - pret a rearmer';
        1: // TEST_A (= CST_STEP_TEST_A)
            Status.OperatorMessage := 'AU: autotest canal A en cours';
        2: // RESTORE_A (= CST_STEP_RESTORE_A)
            Status.OperatorMessage := 'AU: restauration canal A';
        3: // TEST_B (= CST_STEP_TEST_B)
            Status.OperatorMessage := 'AU: autotest canal B en cours';
        4: // RESTORE_B (= CST_STEP_RESTORE_B)
            Status.OperatorMessage := 'AU: restauration canal B';
        5: // PULSE (= CST_STEP_PULSE)
            Status.OperatorMessage := 'AU: impulsion rearmement contacteur';
        6: // CONFIRM (= CST_STEP_CONFIRM)
            Status.OperatorMessage := 'AU: attente confirmation contacteur';
    END_CASE;
END_IF;
{endregion}

// ── 1. FRONT RESET AVANT GATE ───────────────────────────────────────────
ResetEdge(CLK := Reset);

IF NOT Enable OR NOT PowerContactorEngaged THEN
    BrakeTimeout(IN := FALSE, PT := T#500ms);
    DriveControlWord := 0;
    DriveFreqCmd_Hz := 0.0;
    DriveFreqCmdWord := 0;
    BrakeCmd := FALSE;
    BrakeTimeoutElapsed := T#0ms;
    Ready := FALSE;
    Reason := E_TranslationFinalInterlockReason.NONE;
    RETURN;
END_IF;

MovementRequested := (RequestedDriveControlWord = 1) OR (RequestedDriveControlWord = 2);
PermitFinalBlocked := ((RequestedDriveControlWord = 1) AND NOT EffectivePermitM3_Tremie)
                   OR ((RequestedDriveControlWord = 2) AND NOT EffectivePermitM3_Maintenance);

// ── 2. Watchdog : exclusivement après ordre effectif de desserrage ──────
BrakeTimeout(
    IN := BrakeReleaseRequest AND NOT BrakeCommandOpenConfirmed AND NOT RestartInhibit,
    PT := T#500ms
);
BrakeTimeoutElapsed := BrakeTimeout.ET;

IF BrakeTimeout.Q THEN
    BrakeTimeoutCause := TRUE;
ELSIF BrakeCommandOpenConfirmed THEN
    BrakeTimeoutCause := FALSE;
END_IF;

BrakeTimeoutCauseEdge(CLK := BrakeTimeoutCause);
IF BrakeTimeoutCauseEdge.Q THEN
    BrakeTimeoutAck := FALSE;
    RestartInhibit := TRUE;
    ResetRequired := TRUE;
    NeutralRequestSeen := FALSE;
    Reason := E_TranslationFinalInterlockReason.BRAKE_COMMAND_NOT_CONFIRMED;
END_IF;

IF ResetEdge.Q THEN
    BrakeTimeoutAck := TRUE;
    ResetRequired := FALSE;
END_IF;

instCauses[0].Active   := BrakeTimeoutCause OR NOT BrakeTimeoutAck;
instCauses[0].Latching := TRUE;
instCauses[0].Texte    := 'Timeout confirmation ouverture frein translation';

instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;

// ── 3. Réarmement anti-redémarrage automatique ──────────────────────────
IF RestartInhibit AND NOT Fault.Error AND NOT ResetRequired AND NOT ResetEdge.Q THEN
    IF RequestedDriveControlWord = 0 THEN
        NeutralRequestSeen := TRUE;
    ELSIF NeutralRequestSeen AND MovementRequested THEN
        RestartInhibit := FALSE;
        NeutralRequestSeen := FALSE;
    END_IF;
END_IF;

// ── 4. Décision finale : zéro couple utile sans confirmation frein ──────
DriveControlWord := 0;
DriveFreqCmd_Hz := 0.0;
DriveFreqCmdWord := 0;

BrakeCmd := BrakeReleaseRequest AND NOT Fault.Error AND NOT RestartInhibit;
Ready := NOT Fault.Error AND NOT RestartInhibit;

IF Fault.Error THEN
    BrakeCmd := FALSE;
ELSIF RequestedDriveControlWord = 7 THEN
    DriveControlWord := 7;
ELSIF RestartInhibit THEN
    Reason := E_TranslationFinalInterlockReason.RESTART_INHIBITED;
ELSIF MovementRequested AND NOT PermitFinalBlocked THEN
    IF BrakeReleaseRequest AND BrakeCommandOpenConfirmed THEN
        DriveControlWord := RequestedDriveControlWord;
        DriveFreqCmd_Hz := MAX(0.0, RequestedDriveFreqHz);
    END_IF;
END_IF;

// ── 5. Mise à l'échelle finale REAL Hz -> WORD registre PDO 0x3100 ──────
DriveFreqCmdWord := REAL_TO_WORD(LIMIT(0.0, DriveFreqCmd_Hz, DriveFreqWordMaxHz) * DriveFreqWordScale);

// ── 1. FRONT RESET AVANT GATE ───────────────────────────────────────────
// Le front est échantillonné même pendant Enable/AU faux : un Reset maintenu
// pendant une gate ne devient jamais un faux acquittement au retour.
ResetEdge(CLK := Reset);

// ── 2. GATE : neutralisation sûre ───────────────────────────────────────
// ErrorId, RestartInhibit et ResetRequired ne sont jamais effacés par une perte
// Enable/AU : celle-ci coupe uniquement les sorties. Le retour exige toujours un
// acquittement conscient puis une nouvelle demande opérateur.
IF NOT Enable OR NOT PowerContactorEngaged THEN
    BrakeTimeout(IN := FALSE, PT := T#500ms);
    StepDelay(IN := FALSE, PT := T#1s250ms);
    RestartDelay(IN := FALSE, PT := T#1000ms);
    DeadTime(IN := FALSE);
    DeadTimePending := FALSE;
    DeadTimeElapsed := T#0ms;
    // 🔒 Transitoires §3bis neutralisés à la gate (latches de sûreté conservés ci-dessous).
    SenseHoldActive := FALSE; SenseHoldDone := FALSE;
    SenseHoldTimer(IN := FALSE); SenseHoldFeedbackTimer(IN := FALSE);
    SenseHoldElapsed := T#0ms;
    ContactorStuck := ContactorStuckLatched;
    ReleaseOrderActive := FALSE; ReleaseOrderDone := FALSE;
    ReleaseOrderTimer(IN := FALSE, PT := ReleaseOrderDelay);
    ReleaseOrderElapsed := T#0ms;
    RelayFwd := FALSE; RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    BrakeCmd := FALSE; AuthorizedStep := 0;
    BrakeTimeoutElapsed := T#0ms; RestartDelayElapsed := T#0ms; StepDelayElapsed := T#0ms;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    Error := (ErrorId <> 16#0000);
    State := E_WinchFinalInterlockState.DISABLED;
    RestartRequired := TRUE;
    // 🔒 Sorties de diagnostic et latches de sûreté VOLONTAIREMENT conservés hors Enable (AC3 / §9) :
    // - ErrorId & RestartInhibit : latches défaut et anti-redémarrage auto (doivent survivre à la perte d'Enable, acquittement conscient requis)
    // - StateAtError & Reason : snapshot d'état et cause de blocage préservés pour diagnostic IHM
    RETURN;
END_IF;

RequestedStepClamped := LIMIT(0, RequestedStep, 5);
// 🛡️ SafeStop : coupure dure à la barrière finale (défense en profondeur).
// SafeStop est consommé en §5 : quand TRUE, RelayFwd/Rev, contacteurs et frein
// sont coupés indépendamment de FB_Winch. Enable reste actif (≠ neutralisation) ;
// SafeStop n'est pas un défaut (pas de FAULT, pas de latch, pas de Reset requis).
MotorRequest := (RequestedStepClamped > 0) AND (RequestedRelayFwd XOR RequestedRelayRev);
// Defense en profondeur : le meme permis directionnel que celui applique en amont
// doit encore autoriser la sortie finale. Aucun latch ni defaut n'est cree ici :
// la demande est simplement neutralisee tant que le permis est FALSE.
PermitFinalBlocked := (RequestedRelayFwd AND NOT AscentPermit)
                   OR (RequestedRelayRev AND NOT DescendPermit);

// ── 2bis. Arbitrage Error/ErrorId AVANT §3/§5 ────────────────────────────
// ErrorId bit0 (défaut frein) est mis à jour en FIN de scan (§6bis, après BrakeCmd) —
// la valeur lue ici est donc celle de la fin du scan PRÉCÉDENT (retard d'un scan sur une
// nouvelle occurrence, ~10ms, négligeable face au budget 500ms du watchdog). Voir bandeau.
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// ── 3. Réarmement anti-redémarrage automatique ──────────────────────────
// Après timeout : cause disparue + front Reset, puis demande moteur à zéro,
// puis nouvelle demande distincte. La retombée + T#1000ms sera ensuite refaite.
IF RestartInhibit AND NOT Error AND NOT ResetRequired AND NOT ResetEdge.Q THEN
    IF NOT MotorRequest THEN
        NeutralRequestSeen := TRUE;
        RestartRequired := TRUE;
    ELSIF NeutralRequestSeen AND MotorRequest THEN
        RestartInhibit := FALSE;
        NeutralRequestSeen := FALSE;
        RestartRequired := TRUE;
        Reason := E_WinchFinalInterlockReason.NONE;
    END_IF;
END_IF;

// ── 4. Mémorisation de l'arrêt : temporisation d'anti-redémarrage chaud ──────────
// La temporisation RestartDelay (1500ms) s'arme à l'arrêt du mouvement (NOT MotorRequest) et
// s'écoule pendant la pause à l'arrêt (au lieu de repartir de zéro à chaque nouvel appui) —
// permet un redémarrage instantané si la pause dépasse 1.5s. Le décompte ne démarre/continue que
// si le moteur n'est plus demandé ET que le frein est physiquement confirmé fermé
// (NOT BrakeFeedback = bobine retombée, mâchoires serrées). Garde le comportement "purge pendant
// la pause" (RestartRequired ne s'arme qu'à NOT MotorRequest, indépendant de la tempo).
IF NOT MotorRequest THEN
    RestartRequired := TRUE;
END_IF;
RestartDelay(IN := RestartRequired AND NOT MotorRequest AND NOT BrakeFeedback AND NOT RestartInhibit, PT := T#1500ms);
RestartDelayElapsed := RestartDelay.ET;
IF RestartDelay.Q THEN
    RestartRequired := FALSE;
END_IF;

// ── 4bis. Temps mort directionnel (TC-P10-021/022) ─────────────────────────────
// Distinct du RestartDelay (anti-court-cycle uniforme) : temps mort de redémarrage
// après arrêt, dépendant du sens de la nouvelle demande. Même sens → DeadTimeSameDir ;
// inversion → DeadTimeOppositeDir. Neutre↔sens = immédiat (pas de temps mort à l'armement).
// Le décompte se fait pendant la pause ET pendant l'attente après nouvelle demande
// (purge pendant la pause, comme RestartDelay). PT = DeadTimeOppositeDir (le plus long) ;
// à la nouvelle demande, on vérifie si le temps mort requis pour le sens réel est déjà
// écoulé (cas même sens, plus court).
IF MotorRequest THEN
    IF RequestedRelayFwd THEN
        LastDirection := 1;
    ELSE
        LastDirection := -1;
    END_IF;
END_IF;

IF NOT MotorRequest THEN
    DeadTimePending := TRUE;
END_IF;

DeadTime(IN := DeadTimePending AND NOT BrakeFeedback AND NOT RestartInhibit, PT := DeadTimeOppositeDir);
DeadTimeElapsed := DeadTime.ET;
IF DeadTime.Q THEN
    DeadTimePending := FALSE;
END_IF;

IF MotorRequest AND DeadTimePending THEN
    IF RequestedRelayFwd THEN
        NewDirection := 1;
    ELSE
        NewDirection := -1;
    END_IF;
    IF NewDirection = LastDirection THEN
        RequiredDeadTime := DeadTimeSameDir;
    ELSE
        RequiredDeadTime := DeadTimeOppositeDir;
    END_IF;
    IF DeadTime.ET >= RequiredDeadTime THEN
        DeadTimePending := FALSE;
    END_IF;
END_IF;

// ── 4ter. Maintien borné du contacteur de sens (§3bis) — AC6/AC7/AC8 ─────────
// Règle §3bis : quand RequestedStep retombe à 0 mais RequestedRelayFwd/Rev reste
// TRUE (demande transitoire de chute de palier portée par FB_Winch), la barrière NE
// force PLUS RelayFwd/Rev à FALSE immédiatement — elle TIENT le contacteur de sens
// (jamais relâché avant les contacteurs de vitesse) jusqu'à :
//   - FwdRevSpeedFeedbackOff confirmé, debounced par DropConfirmDelay (AC7 : pas
//     d'ouverture du sens sur retour simple voie seul) ; OU
//   - T_max (MaxSenseHoldTime) écoulé -> chute du sens FORCÉE + latch ContactorStuck.
// Le maintien indéfini du stator sous tension est INTERDIT (AC7). Les coupures dures
// (NOT Enable / PowerContactorEngaged=FALSE / Error / RestartInhibit) ne passent
// JAMAIS par ce maintien (AC9) : elles coupent RelayFwd/Rev immédiatement.
SenseHoldRequested := (RequestedStepClamped = 0) AND (RequestedRelayFwd OR RequestedRelayRev)
                      AND NOT Error AND NOT RestartInhibit AND NOT ContactorStuckLatched;

IF NOT Enable OR NOT PowerContactorEngaged THEN
    // 🔒 Gate dur : pas de maintien possible (les sorties sont déjà coupées §2).
    SenseHoldActive := FALSE; SenseHoldDone := FALSE;
    SenseHoldTimer(IN := FALSE, PT := MaxSenseHoldTime);
    SenseHoldFeedbackTimer(IN := FALSE, PT := DropConfirmDelay);
ELSIF Error OR RestartInhibit THEN
    // Coupure par défaut : le maintien ne survit pas à un défaut (AC9).
    SenseHoldActive := FALSE; SenseHoldDone := FALSE;
    SenseHoldTimer(IN := FALSE); SenseHoldFeedbackTimer(IN := FALSE);
ELSE
    IF MotorRequest THEN
        SenseHoldDone := FALSE;
        SenseHoldActive := FALSE;               // vraie nouvelle demande interrompt le maintien transitoire
    END_IF;
    IF NOT (RequestedRelayFwd OR RequestedRelayRev) THEN
        SenseHoldDone := FALSE;
        SenseHoldActive := FALSE;               // retour au neutre complet : plus rien a tenir
    END_IF;
    IF SenseHoldRequested AND NOT SenseHoldActive AND NOT SenseHoldDone THEN
        SenseHoldActive := TRUE;              // entrée en maintien §3bis
        SenseHoldTimer(IN := FALSE, PT := MaxSenseHoldTime);        // T_max arme au scan suivant
        SenseHoldFeedbackTimer(IN := FALSE, PT := DropConfirmDelay);
    ELSIF SenseHoldActive THEN
        SenseHoldFeedbackTimer(IN := FwdRevSpeedFeedbackOff, PT := DropConfirmDelay);
        SenseHoldTimer(IN := NOT FwdRevSpeedFeedbackOff, PT := MaxSenseHoldTime);
        IF SenseHoldFeedbackTimer.Q THEN
            // Retombée contacteurs CONFIRMÉE -> chute normale du sens (one-shot).
            SenseHoldActive := FALSE; SenseHoldDone := TRUE;
        ELSIF SenseHoldTimer.Q THEN
            // T_max sans confirmation -> chute du sens FORCÉE + latch à acquitter (AC7).
            SenseHoldActive := FALSE;
            ContactorStuckLatched := TRUE;
        END_IF;
    ELSE
        SenseHoldTimer(IN := FALSE); SenseHoldFeedbackTimer(IN := FALSE);
    END_IF;
END_IF;
SenseHoldElapsed := SenseHoldTimer.ET;
ContactorStuck := ContactorStuckLatched;

// ── 4quater. Ordre de relâchement contacteurs (vitesse avant direction) ──
// Quand le mouvement s'arrête (NOT MotorRequest ou SafeStop), les contacteurs
// de VITESSE (Contactor1-4) sont relâchés immédiatement, puis le contacteur de
// DIRECTION (RelayFwd/Rev) après ReleaseOrderDelay (>= 100ms). Protège le moteur :
// on ne coupe jamais la direction pendant que la vitesse est encore engagée.
// Les coupures dures (NOT Enable / PowerContactorEngaged / Error / RestartInhibit)
// restent immédiates (AC9) — l'ordre ne s'applique qu'à l'arrêt commandé.
// Le maintien transitoire §3bis (SenseHold) garde la priorité : quand il est actif,
// c'est lui qui tient la direction (jusqu'à confirmation retombée), pas cet ordre.
IF MotorRequest AND NOT SafeStop THEN
    // Nouvelle demande de mouvement : l'ordre de relâchement est réarmé.
    ReleaseOrderActive := FALSE;
    ReleaseOrderDone := FALSE;
    ReleaseOrderTimer(IN := FALSE, PT := ReleaseOrderDelay);
ELSIF (NOT MotorRequest OR SafeStop) AND NOT ReleaseOrderActive AND NOT ReleaseOrderDone
      AND (RequestedRelayFwd OR RequestedRelayRev) AND NOT SenseHoldActive THEN
    // Arrêt commandé : entrée en ordre de relâchement (vitesse relâchée, direction tenue).
    ReleaseOrderActive := TRUE;
END_IF;

// ── 5. Autorisation moteur ────────────────────────────────────────────────
RelayFwd := FALSE; RelayRev := FALSE;
Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
Busy := FALSE; Done := FALSE; Ready := NOT Error AND NOT ContactorStuckLatched;

IF Error THEN
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    State := E_WinchFinalInterlockState.FAULT;
ELSIF RestartInhibit THEN
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    Reason := E_WinchFinalInterlockReason.RESTART_INHIBITED;
    State := E_WinchFinalInterlockState.FAULT;
ELSIF ContactorStuckLatched THEN
    // AC7 : T_max §3bis dépassé sans confirmation retombée -> chute du sens FORCÉE.
    // RelayFwd/Rev et BrakeCmd (= RelayFwd OR RelayRev) retombent à FALSE ci-dessus.
    // Latch à acquittement conscient (ResetEdge) — jamais de redémarrage auto.
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    Reason := E_WinchFinalInterlockReason.SENSE_DROP_TIMEOUT;
    State := E_WinchFinalInterlockState.FAULT;
ELSIF ReleaseOrderActive AND NOT PermitFinalBlocked THEN
    // Ordre de relâchement : vitesse relâchée immédiatement, direction tenue
    // jusqu'à ReleaseOrderDelay, puis direction relâchée (AC1/AC2).
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    IF RequestedRelayFwd THEN RelayFwd := TRUE; END_IF;
    IF RequestedRelayRev THEN RelayRev := TRUE; END_IF;
    ReleaseOrderTimer(IN := TRUE, PT := ReleaseOrderDelay);
    ReleaseOrderElapsed := ReleaseOrderTimer.ET;
    IF ReleaseOrderTimer.Q THEN
        ReleaseOrderActive := FALSE;
        ReleaseOrderDone := TRUE;
        RelayFwd := FALSE; RelayRev := FALSE;
    END_IF;
    State := E_WinchFinalInterlockState.READY;
    Busy := TRUE;
ELSIF SafeStop OR PermitFinalBlocked THEN
    // 🛡️ SafeStop ou permis directionnel refusé : coupure dure indépendante de FB_Winch.
    // SafeStop n'est PAS un défaut : pas de FAULT, pas de latch, pas de Reset requis.
    // Les sorties sont coupées tant que l'une des causes est TRUE ; retour nominal dès sa retombée.
    // BrakeCmd (= RelayFwd OR RelayRev, §6) retombe à FALSE automatiquement.
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    RelayFwd := FALSE; RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    State := E_WinchFinalInterlockState.READY;
ELSIF SenseHoldActive THEN
    // §3bis : RequestedStep retombé à 0 mais sens encore commandé -> on TIENT le
    // contacteur de sens jusqu'à FwdRevSpeedFeedbackOff (debounced DropConfirmDelay)
    // OU T_max. AuthorizedStep=0 (aucun contacteur de vitesse), seul le sens est tenu.
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    IF RequestedRelayFwd THEN RelayFwd := TRUE; END_IF;
    IF RequestedRelayRev THEN RelayRev := TRUE; END_IF;
    State := E_WinchFinalInterlockState.WAIT_SENSE_DROP_CONFIRM;
    Busy := TRUE;
ELSIF NOT MotorRequest THEN
    // Toute annulation de demande annule la temporisation de hausse en cours.
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    State := E_WinchFinalInterlockState.READY;
ELSIF RestartRequired OR DeadTimePending THEN
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    State := E_WinchFinalInterlockState.WAIT_RESTART_DELAY;
    Busy := TRUE;
ELSE
    // ⚡ Progression de palier directe : la temporisation (tempo palier) est gérée
    // par le métier (FB_Winch). La barrière finale transmet directement la consigne
    // sans micro-coupure des contacteurs.
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := RequestedStepClamped;

    IF (AuthorizedStep > 0) OR (RequestedStepClamped > 0) THEN
        RelayFwd := RequestedRelayFwd;
        RelayRev := RequestedRelayRev;
        Contactor1 := RequestedContactor1;
        Contactor2 := RequestedContactor2;
        Contactor3 := RequestedContactor3;
        Contactor4 := RequestedContactor4;
    END_IF;

    IF NOT BrakeFeedback THEN
        State := E_WinchFinalInterlockState.WAIT_BRAKE_COMMAND_CONFIRMATION;
        Busy := TRUE;
    ELSE
        State := E_WinchFinalInterlockState.READY;
    END_IF;
END_IF;

// ── 6. Commande frein — couplage direct ────────────────────────────────
// BrakeCmd suit STRUCTURELLEMENT RelayFwd/RelayRev, calculé APRÈS leur
// finalisation ci-dessus (§5) : il hérite donc automatiquement de toutes leurs
// conditions de sécurité (Error, RestartInhibit, RestartRequired, MotorRequest)
// sans avoir à les répéter. Aucun risque d'écart frein/mouvement possible : le
// frein ne PEUT pas être commandé ouvert sans qu'un des deux relais de sens le
// soit aussi, puisque c'est la même expression. PRG_06_Outputs recalcule la
// MÊME expression indépendamment sur les DQ finaux (M1RelayFwd OR M1RelayRev)
// pour piloter physiquement la bobine — ce BrakeCmd ici sert de miroir/diagnostic
// (State, IHM) mais n'est plus câblé sur la sortie physique (voir PRG_06 §2).
BrakeCmd := RelayFwd OR RelayRev;

// ── 6bis. Watchdog frein : uniquement sur la commande RÉELLEMENT FINALE ────
// Watchdog armé sur BrakeCmd (fin §5/§6), JAMAIS sur RequestedRelayFwd/Rev (demande amont pas
// encore autorisée par le state-machine §5 — RestartRequired peut la retenir jusqu'à T#1000ms,
// largement > le seuil 500ms ci-dessous, ce qui déclencherait un faux défaut à chaque redémarrage
// normal).
BrakeTimeout(IN := BrakeCmd AND NOT BrakeFeedback AND NOT RestartInhibit, PT := T#500ms);
BrakeTimeoutElapsed := BrakeTimeout.ET;
IF BrakeTimeout.Q THEN
    BrakeTimeoutCause := TRUE;
ELSIF BrakeFeedback THEN
    BrakeTimeoutCause := FALSE;   // cause réellement disparue (retour desserrage confirmé)
END_IF;
BrakeTimeoutCauseEdge(CLK := BrakeTimeoutCause);
IF BrakeTimeoutCauseEdge.Q THEN
    BrakeTimeoutAck := FALSE;    // nouvelle occurrence -> ré-alarme, ack remis à zéro
    RestartInhibit := TRUE;
    ResetRequired := TRUE;
    NeutralRequestSeen := FALSE;
    RestartRequired := TRUE;
    Reason := E_WinchFinalInterlockReason.BRAKE_COMMAND_NOT_CONFIRMED;
END_IF;
IF ResetEdge.Q THEN
    BrakeTimeoutAck := TRUE;     // toujours effectif, sans condition externe
    ResetRequired := FALSE;
    ContactorStuckLatched := FALSE;   // acquittement conscient du latch T_max §3bis (AC7)
END_IF;
IF BrakeTimeoutCause OR NOT BrakeTimeoutAck THEN
    ErrorId := ErrorId OR 16#0001;
ELSE
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// ── 6bis2. Publication Fault transverse (socle FB_FaultCore) ──────────────
// 🧩 Homogénéisation interface (AF-03 §3) : le défaut est exposé sous la forme
// standard Fault:ST_Fault (comme FB_TranslationOutputInterlock) au lieu du plat
// Error/ErrorId. La cause unique bit0 = timeout frein, strictement identique à la
// gate interne (ErrorId) ; Latching reproduit le latch existant restitué au front
// Reset (jamais de re-armement auto). La gate interne (Error/ErrorId) reste
// inchangée — la publication n'ajoute ni ne modifie aucune coupure.
instCauses[0].Active   := ((ErrorId AND 16#0001) <> 16#0000);
instCauses[0].Latching := TRUE;
instCauses[0].Texte    := 'Timeout confirmation ouverture frein treuil';
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;

// ── 6ter. Synchronisation defaut frein en fin de scan (TC-P10-012/013/020) ──
// ErrorId bit0 (defaut frein) est pose en §6bis, APRES la machine d'etat §5.
// Sans ce bloc, la synthese Error et l'etat FAULT accusaient un retard d'un scan
// (~10 ms) sur le watchdog frein. On resynchronise Error/State et on coupe les
// sorties le MEME scan que l'apparition du defaut : c'est un defaut FINAL, coupure
// immediate (jamais un maintien ordonne §3bis).
Error := (ErrorId <> 16#0000);
IF Error THEN
    RelayFwd := FALSE; RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    BrakeCmd := FALSE;
    AuthorizedStep := 0;
    Busy := FALSE; Done := FALSE; Ready := FALSE;
    State := E_WinchFinalInterlockState.FAULT;
END_IF;

{region "§1 Reset (front, toujours effectif)"}
// Front Reset : efface tous les latches. Jamais conditionné, agit même Enable=FALSE (§9).
Ready := Enable;
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    FOR i := 0 TO 15 DO Latch[i] := FALSE; END_FOR;
END_IF;
{endregion}

{region "§2 Vue LIVE — Error / ErrorId"}
// Bitfield des causes présentes MAINTENANT. Retombe seule à 0 quand les causes disparaissent.
// Non évaluée si Enable=FALSE (pas de lecture de cause hors autorisation).
Fault.ErrorId := 0;
IF Enable THEN
    FOR i := 0 TO 15 DO
        IF Causes[i].Active THEN
            Fault.ErrorId := Fault.ErrorId OR SHL(WORD#1, INT_TO_DWORD(i));
        END_IF;
    END_FOR;
END_IF;
Fault.Error := (Fault.ErrorId <> 0);
{endregion}

{region "§3 Armement des latches (causes à acquitter)"}
// Une cause Active ET Latching arme son bit ; le bit reste jusqu'au front Reset (§1),
// même si la cause disparaît. Réapparition => ré-armement (ré-alarme).
IF Enable THEN
    FOR i := 0 TO 15 DO
        IF Causes[i].Active AND Causes[i].Latching THEN
            Latch[i] := TRUE;
        END_IF;
    END_FOR;
END_IF;
{endregion}

{region "§4 Vue LATCHÉE — Latched / LatchedId"}
// Toujours publiée, y compris Enable=FALSE : un défaut non acquitté reste visible.
Fault.LatchedId := 0;
FOR i := 0 TO 15 DO
    IF Latch[i] THEN
        Fault.LatchedId := Fault.LatchedId OR SHL(WORD#1, INT_TO_DWORD(i));
    END_IF;
END_FOR;
Fault.Latched := (Fault.LatchedId <> 0);
{endregion}
